  "be_conversationLoop.roundCapFinalizePrompt": "도구 라운드를 모두 소진해 더 이상 행동할 수 없습니다. 도구를 추가로 호출하지 마세요. 이어받을 사람을 위한 인계문을 작성하세요: 확인한 사실(설명이 아니라 구체적 발견 내용), 진행 중이던 작업, 남은 구체적 다음 단계. 직접적이고 구체적으로 — 이것이 당신 작업에 대해 남는 유일한 보고입니다.",
  "be_conversationLoop.reasoningOnlyContinuePrompt": "직전 응답은 추론뿐이었고 답변도 도구 호출도 없었기 때문에, 사용자에게도 시스템에도 아무것도 전달되지 않았습니다. 그 추론이 다음에 하겠다고 말한 것을 실제로 수행하세요: 도구를 호출하거나, 답변을 작성하세요. 추론을 다시 서술하지 마세요.",
  "be_conversationLoop.guidanceTruncationMarker": "[일부 방향 지시 생략 — {count}개 항목 길이 초과로 폐기됨]\n\n{joined}",
  "be_conversationLoop.guidanceInjectionHeader": "[방향 지시 — 진행 중 추가 입력]\n{joined}",
  "be_conversationLoop.progressNudge": "[진행 상황 알림 — 사용자가 보낸 것이 아니라 호스트가 생성한 메시지]\n이번 턴은 {elapsedSeconds}초 동안 {round}개 라운드를 실행했고, 도구를 {toolCalls}회 호출했으며 그중 {toolErrors}회가 오류를 반환했습니다.\n작업이 이미 완료됐다면 검토만으로 완료를 선언하지 마세요. 해당 작업의 검사를 실행하거나 산출물을 직접 실행한 다음, 무엇을 실행했고 결과가 무엇이었는지 답변에 명시하세요.\n지금 방식이 수렴하지 않는다면 같은 방식을 반복하지 말고 접근 방식을 바꾸세요.",
