  "be_conversationLoop.cmdToolsEmpty": "등록된 도구 없음",
  "be_conversationLoop.cmdHelp": "Ave 명령어:\n/new — 새 대화 시작\n/sessions — 저장된 세션 목록\n/load <ID> — 세션 복원\n/compact — 대화 이력 압축\n/remember <content> — 기억 저장\n/memory — 사용자 기억 목록\n/model [model-id|default] — 이 세션의 모델 확인/변경\n/vendor — 현재 벤더/토큰 정보\n/tools — 등록된 도구 목록\n/permission — 현재 권한 모드\n/permission mode <strict|default|auto|allow> --durable — 권한 모드 변경 (strict: 기본, default: 쓰기 허용, auto, allow: 허용)\n/permission dir <list|allow|deny> [path] — 허용 디렉터리 관리\n/permission reviewer <show|mode|fallback> [value] — 리뷰어 설정\n/permission audit <show|verify> — 권한 감사 조회/검증\n/permission hooks <list|accept|disable|reject> [name] — script hook 신뢰 상태 관리\n/help — 이 도움말",
