  "be_mcpManager.configFileInvalid": "MCP 서버 설정 파일 {path}이(가) \"servers\" 목록을 가진 올바른 JSON이 아닙니다. 파일을 고치거나 옮기세요. Ave는 이 파일을 덮어쓰지 않습니다.",
