  "formatIpcError.subscriptionRuntimeUnauthenticated": "구독 실행 환경의 배포자를 확인할 수 없습니다. 공식 설치 안내에 따라 서명을 확인하거나 다시 설치한 뒤 다시 확인하세요.",
  "formatIpcError.subscriptionRuntimeReleaseMetadataUnavailable": "구독 실행 환경의 릴리스를 확인하지 못했습니다. Linux에서는 downloads.claude.ai에서 Anthropic이 서명한 릴리스 매니페스트를 받아 확인하는데, 이 호스트에 연결할 수 없었습니다. downloads.claude.ai로의 HTTPS 연결(직접 또는 시스템 프록시 경유)을 허용한 뒤 다시 확인하세요. 오프라인으로 확인을 건너뛰는 방법은 없습니다.",
