  "formatIpcError.processEntryRequiresPinnedArtifact": "이 익스텐션은 자체 프로그램을 실행하므로, Ave는 sha256 해시로 고정된 마켓플레이스 릴리스 또는 아카이브에서만 설치합니다. 그래서 이 사본은 거부되었습니다. 릴리스를 고정한 마켓플레이스에서 설치하세요. 직접 설치나 로컬 설치는 항상 거부됩니다.",
