  "permissionsTab.osSandboxCapabilityLinux": "Linux(bwrap): 명령은 프로젝트와 임시 폴더에만 쓰고, 네트워크는 허용한 호스트로만 나갑니다.",
  "permissionsTab.osSandboxCapabilityOther": "파일과 프로세스는 격리되며, 네트워크 격리는 보장되지 않습니다.",
  "permissionsTab.osSandboxCapabilityWindows": "Windows: Windows가 Microsoft Execution Containers를 제공하면 셸 명령은 명령마다 별도 컨테이너에서 실행됩니다. 익스텐션은 srt-win 샌드박스 계정 하나를 함께 쓰므로 익스텐션끼리는 격리되지 않습니다. 샌드박스가 꺼져 있는 동안 도구는 격리 없이 실행됩니다.",
