  "permissionsTab.osSandboxDiagnosticHint": "시작 진단에 실패했습니다. 샌드박스 설정을 복구한 뒤 Ave를 재시작하세요.",
  "permissionsTab.osSandboxInitFailedHint": "샌드박스가 시작 점검은 통과했지만 이번 세션에서 시작하지 못했습니다. 원인은 로그에 있으며, Ave를 재시작하면 다시 시도합니다.",
  "permissionsTab.osSandboxShellStatusError": "셸이 샌드박스에서 실행되는지 Ave가 판단하지 못했습니다. 호스트 오류이니 로그를 확인하세요.",
