  "permissionsTab.osSandboxWindowsExtensionReasonRuntimeUnavailable": "이번 세션에 Windows 샌드박스 런타임이 시작되지 않았습니다",
  "permissionsTab.osSandboxWindowsExtensionsDisclosureHeading": "Windows 컨테이너가 숨기거나 막지 않는 것",
  "permissionsTab.osSandboxWindowsExtensionsNetwork": "네트워크: 컨테이너 안 프로세스는 자기 전용 프록시 주소·포트로만 외부에 연결할 수 있습니다. Windows 는 그 프록시 엔드포인트를 어떤 호스트 프로세스가 소유하는지 확인하지 않습니다. 루프백은 양방향으로 요청되며, 들어오는 연결 보호는 Windows 방화벽에 의존하고, 이름 조회(DNS)는 호스트 리졸버를 거칩니다.",
  "permissionsTab.osSandboxWindowsExtensionsWindows": "창: 컨테이너 안 프로세스도 데스크톱에 창을 띄울 수 있으니 신뢰하지 마세요. 클립보드 접근과 입력 주입은 꺼져 있습니다.",
  "permissionsTab.osSandboxWindowsExtensionsFolderNames": "폴더 이름: 컨테이너는 자기 폴더까지 이어지는 경로의 폴더 이름과 메타데이터(내용은 아님)를 볼 수 있고, 그 아래 하위 폴더까지 목록이 보입니다. 사용자 프로필 안의 이름(예: Documents), Ave 데이터 폴더 안의 이름, 다른 익스텐션 ID 가 드러날 수 있습니다.",
  "permissionsTab.osSandboxWindowsExtensionsTemp": "임시 파일: Windows 는 컨테이너의 임시 파일을 Ave 데이터 폴더 아래 그 컨테이너 전용 스테이징 폴더 안의 프로필 폴더에 둡니다.",
  "permissionsTab.osSandboxWindowsExtensionsDll": "DLL: 컨테이너 안 프로세스의 작업 폴더·PATH 폴더·쓰기 가능한 폴더에 놓인 DLL 은 그 프로세스가 로드할 수 있습니다. 그 컨테이너 안에 머물지만 Ave 가 막지는 않습니다.",
  "permissionsTab.osSandboxWindowsExtensionsBashHooks": "Git Bash: Bash 훅은 컨테이너에서 시작할 수 없습니다. 익스텐션의 Bash 훅은 거부되고, 셸도 컨테이너에서 실행 중이면 사용자 Bash 훅도 거부됩니다. 컨테이너 셸 밖의 사용자 훅은 기존 경로를 유지합니다.",
  "permissionsTab.osSandboxWindowsExtensionsEnvironment": "환경 변수: NODE_OPTIONS 나 NODE_PATH 를 설정한 MCP 서버·훅은 srt-win 에서는 시작되더라도 컨테이너에서는 거부됩니다.",
  "permissionsTab.osSandboxWindowsExtensionsReviewer": "리뷰어: 권한 리뷰어에게는 MCP 서버가 샌드박스 안에 있는지만 전달되고, 컨테이너와 srt-win 중 무엇이 격리하는지는 전달되지 않습니다.",

