  "pluginConfigTab.doctorManifestValidationTitle": "익스텐션 manifest 검증 실패",
  "pluginConfigTab.doctorManifestValidationDescription": "익스텐션 manifest가 현재 스키마와 일치하지 않습니다. 아래 상세 필드 오류를 확인한 뒤 업데이트된 마켓플레이스 패키지를 다시 설치하거나 로컬 설치를 제거하세요.",
  "pluginConfigTab.doctorIncompatibleAppTitle": "앱 업데이트 필요",
  "pluginConfigTab.doctorIncompatibleAppDescription": "이 익스텐션은 더 높은 버전의 Ave가 필요합니다. 다시 설치해도 해결되지 않으며, 앱을 업데이트한 뒤 익스텐션을 다시 로드하세요. 제거할 수도 있습니다.",
  "pluginConfigTab.doctorIncompatibleProtocolTitle": "다른 Ave 프로토콜용 익스텐션",
  "pluginConfigTab.doctorIncompatibleProtocolDescription": "이 익스텐션은 이 앱이 제공하지 않는 Ave 익스텐션 프로토콜 버전을 사용하거나, 이 앱에 없는 호스트 기능을 필요로 합니다. 다시 설치해도 해결되지 않으며, 이 앱용으로 빌드된 익스텐션 버전을 설치하거나 앱을 업데이트하세요. 제거할 수도 있습니다.",
  "pluginConfigTab.doctorRevokedTitle": "익스텐션 버전 차단됨",
  "pluginConfigTab.doctorRevokedDescription": "마켓플레이스가 보안상의 이유로 이 버전을 차단했습니다. 다시 설치해도 동일하게 차단된 버전을 받아오므로 해결되지 않습니다. 제거하거나 업데이트된 버전을 기다리세요.",
  "pluginConfigTab.doctorUntrustedManifestPathTitle": "익스텐션 레지스트리 항목 거부됨",
  "pluginConfigTab.doctorUntrustedManifestPathDescription": "이 익스텐션의 레지스트리 항목이 익스텐션 폴더 밖의 매니페스트를 가리켜 Ave가 읽기를 거부했습니다. 마켓플레이스에서 다시 설치하면 올바른 위치로 항목이 다시 기록됩니다. 익스텐션을 제거할 수도 있습니다.",
