  "sandboxPolicy.quarantined": "샌드박스가 보호하는 Git 항목을 삭제하지 않고 격리 위치로 옮겼습니다:\n{moves}\n내용을 확인한 뒤 표시된 격리 경로에서 원래 경로로 각 항목을 복원하세요.",
